INSERT INTO LandingPages (Slug, TitleAr, TitleEn, TitleFr, IntroAr, IntroEn, IntroFr, FaqJson, FilterJson, IsPublished, SortOrder, CreatedAt, UpdatedAt) VALUES (N'arab-world', N'فرص لشباب الوطن العربي: منح ووظائف وزمالات مفتوحة الآن', N'Opportunities for youth in the Arab world, open now', N'Opportunités pour les jeunes du monde arabe, ouvertes maintenant', N'كل الفرص المفتوحة الآن لشباب الوطن العربي في مكان واحد: منح دراسية ممولة بالكامل، وظائف خضراء، زمالات، تدريب، تطوع، مؤتمرات ومسابقات. تُعرض هنا الفرص التي تقبل المتقدمين من أي دولة عربية (أو من العالم كله)، لا تلك المحصورة بدولة واحدة. كل فرصة مكتوبة بالعربية والإنجليزية والفرنسية مع شروط الأهلية والموعد النهائي ورابط التقديم الرسمي، ونحدّث القائمة يوميًا ونزيل ما انتهى. رشّح بالنوع أو المرحلة أو المجال أو التمويل، أو جرّب «بوصلة» لتعرف في دقيقتين ما تؤهَّل له أنت تحديدًا.', N'Every opportunity open right now to youth across the Arab world, in one place: fully funded scholarships, green jobs, fellowships, internships, volunteering, conferences and competitions. This page lists opportunities that accept applicants from any Arab country (or from anywhere in the world), not those limited to a single country. Each one is written in Arabic, English and French with its eligibility criteria, deadline and official application link; we update the list daily and remove what has closed. Filter by type, level, field or funding, or try the Compass to see in two minutes what you personally qualify for.', N'Toutes les opportunités ouvertes maintenant aux jeunes du monde arabe, au même endroit : bourses entièrement financées, emplois verts, fellowships, stages, bénévolat, conférences et concours. Cette page présente les opportunités qui acceptent les candidats de n''importe quel pays arabe (ou du monde entier), et non celles réservées à un seul pays. Chacune est rédigée en arabe, anglais et français avec ses critères, sa date limite et le lien officiel ; la liste est mise à jour chaque jour. Filtrez par type, niveau, domaine ou financement, ou essayez la Boussole.', @faq, N'{"type":[],"country":"XA","field":[]}', 1, 22, GETDATE(), GETDATE());
INSERT INTO LandingPages (Slug, TitleAr, TitleEn, TitleFr, IntroAr, IntroEn, IntroFr, FaqJson, FilterJson, IsPublished, SortOrder, CreatedAt, UpdatedAt) VALUES (N'fully-funded', N'فرص ممولة بالكامل لشباب الوطن العربي', N'Fully funded opportunities for youth in the Arab world', N'Opportunités entièrement financées pour les jeunes du monde arabe', N'منح وزمالات ومؤتمرات وبرامج تدريب تغطي كل التكاليف: الرسوم الدراسية أو رسوم المشاركة، السفر، الإقامة، وغالبًا راتبًا شهريًا أو مصروفًا. نصنّف الفرصة «ممولة بالكامل» فقط حين يذكر المصدر ذلك صراحةً، فما تراه هنا لا يحتاج منك سوى التقديم. كل فرصة بثلاث لغات مع الدول المقبولة والمرحلة المطلوبة وشهادة اللغة إن طُلبت والموعد النهائي ورابط التقديم الرسمي. المنافسة على الممولة بالكامل أشد، لذلك ابدأ مبكرًا، وجهّز أوراقك من قائمة «جاهزيتك» في بوصلتك.', N'Scholarships, fellowships, conferences and training programmes that cover everything: tuition or participation fees, travel, accommodation and often a monthly stipend. We label an opportunity “fully funded” only when the source says so explicitly, so what you see here needs nothing from you but an application. Each one comes in three languages with accepted countries, required level, language test if any, deadline and the official link. Competition for fully funded opportunities is tougher, so start early and prepare your documents from the readiness list in your Compass.', N'Bourses, fellowships, conférences et formations qui couvrent tout : frais de scolarité ou de participation, voyage, hébergement et souvent une allocation mensuelle. Nous n''étiquetons une opportunité « entièrement financée » que lorsque la source le dit explicitement. Chacune est en trois langues avec les pays acceptés, le niveau requis, le test de langue éventuel, la date limite et le lien officiel. La concurrence est plus forte : commencez tôt et préparez vos documents depuis la liste de préparation de votre Boussole.', N'{"ar":[{"q":"\u0645\u0627\u0630\u0627 \u064A\u0639\u0646\u064A \u00AB\u0645\u0645\u0648\u0644\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u00BB \u0647\u0646\u0627\u061F","a":"\u0623\u0646 \u0627\u0644\u0645\u0635\u062F\u0631 \u0630\u0643\u0631 \u0635\u0631\u0627\u062D\u0629\u064B \u062A\u063A\u0637\u064A\u0629 \u0627\u0644\u0631\u0633\u0648\u0645 \u0648\u0627\u0644\u0633\u0641\u0631 \u0648\u0627\u0644\u0625\u0642\u0627\u0645\u0629 (\u0648\u063A\u0627\u0644\u0628\u064B\u0627 \u0631\u0627\u062A\u0628\u064B\u0627). \u0627\u0644\u0641\u0631\u0635 \u0627\u0644\u062A\u064A \u0644\u0645 \u064A\u0630\u0643\u0631 \u0645\u0635\u062F\u0631\u0647\u0627 \u0646\u0648\u0639 \u0627\u0644\u062A\u0645\u0648\u064A\u0644 \u0644\u0627 \u062A\u0638\u0647\u0631 \u0641\u064A \u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062D\u0629."},{"q":"\u0647\u0644 \u0623\u062D\u062A\u0627\u062C \u0634\u0647\u0627\u062F\u0629 \u0644\u063A\u0629\u061F","a":"\u0644\u064A\u0633 \u062F\u0627\u0626\u0645\u064B\u0627. \u0627\u0633\u062A\u0639\u0645\u0644 \u0641\u0644\u062A\u0631 \u00AB\u0628\u062F\u0648\u0646 \u0622\u064A\u0644\u062A\u0633\u00BB \u0644\u062A\u0631\u0649 \u0627\u0644\u0645\u0645\u0648\u0644\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0627\u0644\u062A\u064A \u0644\u0627 \u062A\u0637\u0644\u0628 \u0634\u0647\u0627\u062F\u0629\u060C \u0623\u0648 \u062C\u0631\u0651\u0628 \u0627\u0644\u0628\u0648\u0635\u0644\u0629 \u0644\u062A\u0639\u0631\u0641 \u0623\u064A\u0646 \u062A\u0646\u0642\u0635\u0643 \u0634\u0647\u0627\u062F\u0629."},{"q":"\u0643\u064A\u0641 \u0623\u0632\u064A\u062F \u0641\u0631\u0635\u062A\u064A\u061F","a":"\u0642\u062F\u0651\u0645 \u0645\u0628\u0643\u0631\u064B\u0627\u060C \u0648\u0627\u0642\u0631\u0623 \u0634\u0631\u0648\u0637 \u0627\u0644\u0623\u0647\u0644\u064A\u0629 \u062D\u0631\u0641\u064A\u064B\u0627\u060C \u0648\u062C\u0647\u0651\u0632 \u062E\u0637\u0627\u0628 \u0627\u0644\u062F\u0648\u0627\u0641\u0639 \u0648\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u062A\u0648\u0635\u064A\u0629 \u0642\u0628\u0644 \u0627\u0644\u0645\u0648\u0639\u062F \u0628\u0623\u0633\u0627\u0628\u064A\u0639. \u0642\u0627\u0626\u0645\u0629 \u00AB\u062C\u0627\u0647\u0632\u064A\u062A\u0643\u00BB \u0641\u064A \u0627\u0644\u0628\u0648\u0635\u0644\u0629 \u062A\u062C\u0645\u0639 \u0623\u0648\u0631\u0627\u0642\u0643 \u0644\u0643\u0644 \u0627\u0644\u062A\u0642\u062F\u064A\u0645\u0627\u062A."}],"en":[{"q":"What does \u201Cfully funded\u201D mean here?","a":"The source explicitly covers fees, travel and accommodation (and usually a stipend). Opportunities whose source does not state the funding type are not shown on this page."},{"q":"Do I need a language certificate?","a":"Not always. Use the \u201CNo IELTS\u201D filter to see fully funded opportunities that require none, or try the Compass to see where a certificate is the only thing missing."},{"q":"How do I improve my chances?","a":"Apply early, read the eligibility criteria literally, and prepare your motivation letter and recommendation letters weeks before the deadline. The readiness list in your Compass keeps your documents in one place."}],"fr":[{"q":"Que signifie \u00AB enti\u00E8rement financ\u00E9e \u00BB ici ?","a":"La source couvre explicitement les frais, le voyage et l\u0027h\u00E9bergement (et souvent une allocation). Les opportunit\u00E9s sans type de financement pr\u00E9cis\u00E9 n\u0027apparaissent pas ici."},{"q":"Faut-il un certificat de langue ?","a":"Pas toujours. Utilisez le filtre \u00AB Sans IELTS \u00BB, ou essayez la Boussole pour voir o\u00F9 un certificat est la seule chose qui manque."},{"q":"Comment augmenter mes chances ?","a":"Postulez t\u00F4t, lisez les crit\u00E8res \u00E0 la lettre et pr\u00E9parez lettre de motivation et recommandations des semaines \u00E0 l\u0027avance. La liste de pr\u00E9paration de la Boussole centralise vos documents."}]}', N'{"type":[],"funding":"FullyFunded","field":[]}', 1, 23, GETDATE(), GETDATE());
INSERT INTO LandingPages (Slug, TitleAr, TitleEn, TitleFr, IntroAr, IntroEn, IntroFr, FaqJson, FilterJson, IsPublished, SortOrder, CreatedAt, UpdatedAt) VALUES (N'no-ielts', N'منح وفرص بدون آيلتس أو توفل', N'Scholarships and opportunities without IELTS or TOEFL', N'Bourses et opportunités sans IELTS ni TOEFL', N'فرص مفتوحة الآن لا تطلب شهادة IELTS ولا TOEFL: منح تقبل خطاب إثبات اللغة من الجامعة أو مقابلة بدل الاختبار، وزمالات وتدريب وتطوع ومؤتمرات لا تشترط شهادة أصلًا. لا نضع الفرصة هنا إلا إذا قال مصدرها صراحةً إن الشهادة غير مطلوبة؛ الفرص التي لم تذكر اللغة لا تظهر، حتى لا تفاجأ لاحقًا. كل فرصة بثلاث لغات مع الدول المقبولة والمرحلة والموعد ورابط التقديم الرسمي. إن كانت شهادة اللغة هي العائق الوحيد أمامك، فهذه الصفحة هي نقطة البداية.', N'Opportunities open now that require neither IELTS nor TOEFL: scholarships that accept a university proof-of-language letter or an interview instead of the test, plus fellowships, internships, volunteering and conferences that never ask for a certificate. An opportunity appears here only when its source explicitly says the test is not required; those that do not mention language at all are left out so you are not surprised later. Each one comes in three languages with accepted countries, level, deadline and the official link. If a language certificate is the only thing standing in your way, start here.', N'Opportunités ouvertes maintenant qui n''exigent ni IELTS ni TOEFL : bourses acceptant une attestation de langue de l''université ou un entretien, et fellowships, stages, bénévolat et conférences sans certificat. Une opportunité n''apparaît ici que si sa source dit explicitement que le test n''est pas requis ; celles qui ne mentionnent pas la langue sont exclues. Chacune est en trois langues avec pays acceptés, niveau, date limite et lien officiel. Si le certificat de langue est votre seul obstacle, commencez ici.', N'{"ar":[{"q":"\u0647\u0644 \u064A\u0639\u0646\u064A \u0647\u0630\u0627 \u0623\u0646 \u0627\u0644\u0644\u063A\u0629 \u063A\u064A\u0631 \u0645\u0647\u0645\u0629\u061F","a":"\u0644\u0627. \u0627\u0644\u0634\u0647\u0627\u062F\u0629 \u063A\u064A\u0631 \u0645\u0637\u0644\u0648\u0628\u0629\u060C \u0644\u0643\u0646 \u0623\u063A\u0644\u0628 \u0647\u0630\u0647 \u0627\u0644\u0641\u0631\u0635 \u062A\u062F\u0631\u064E\u0651\u0633 \u0623\u0648 \u062A\u064F\u062F\u0627\u0631 \u0628\u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0623\u0648 \u0627\u0644\u0641\u0631\u0646\u0633\u064A\u0629\u060C \u0648\u0642\u062F \u062A\u0637\u0644\u0628 \u062E\u0637\u0627\u0628 \u0625\u062B\u0628\u0627\u062A \u0644\u063A\u0629 \u0645\u0646 \u062C\u0627\u0645\u0639\u062A\u0643 \u0623\u0648 \u0645\u0642\u0627\u0628\u0644\u0629."},{"q":"\u0644\u0645\u0627\u0630\u0627 \u0644\u0627 \u062A\u0638\u0647\u0631 \u0641\u0631\u0635 \u0643\u062B\u064A\u0631\u0629 \u0623\u0639\u0631\u0641 \u0623\u0646\u0647\u0627 \u0628\u0644\u0627 \u0634\u0647\u0627\u062F\u0629\u061F","a":"\u0644\u0623\u0646\u0646\u0627 \u0644\u0627 \u0646\u062F\u0631\u062C \u0627\u0644\u0641\u0631\u0635\u0629 \u0647\u0646\u0627 \u0625\u0644\u0627 \u0625\u0630\u0627 \u0630\u0643\u0631 \u0645\u0635\u062F\u0631\u0647\u0627 \u0635\u0631\u0627\u062D\u0629\u064B \u0623\u0646 \u0627\u0644\u0634\u0647\u0627\u062F\u0629 \u063A\u064A\u0631 \u0645\u0637\u0644\u0648\u0628\u0629. \u0627\u0644\u0641\u0631\u0635 \u0627\u0644\u062A\u064A \u0633\u0643\u062A \u0645\u0635\u062F\u0631\u0647\u0627 \u0639\u0646 \u0627\u0644\u0644\u063A\u0629 \u0644\u0627 \u062A\u064F\u062F\u0631\u062C \u062D\u062A\u0649 \u0644\u0627 \u062A\u0643\u0648\u0646 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629 \u062E\u0627\u0637\u0626\u0629."},{"q":"\u0647\u0644 \u064A\u0645\u0643\u0646\u0646\u064A \u0627\u0644\u062A\u0642\u062F\u064A\u0645 \u062B\u0645 \u0625\u062D\u0636\u0627\u0631 \u0627\u0644\u0634\u0647\u0627\u062F\u0629 \u0644\u0627\u062D\u0642\u064B\u0627\u061F","a":"\u0641\u064A \u0628\u0639\u0636 \u0627\u0644\u0645\u0646\u062D \u0646\u0639\u0645 (\u0627\u0644\u0634\u0647\u0627\u062F\u0629 \u0634\u0631\u0637 \u0644\u0644\u0642\u0628\u0648\u0644 \u0627\u0644\u0646\u0647\u0627\u0626\u064A \u0644\u0627 \u0644\u0644\u062A\u0642\u062F\u064A\u0645). \u0627\u0642\u0631\u0623 \u0634\u0631\u0648\u0637 \u0627\u0644\u0623\u0647\u0644\u064A\u0629 \u0641\u064A \u0635\u0641\u062D\u0629 \u0643\u0644 \u0641\u0631\u0635\u0629."}],"en":[{"q":"Does this mean language doesn\u0027t matter?","a":"No. The certificate is not required, but most of these are taught or run in English or French and may ask for a proof-of-language letter from your university or an interview."},{"q":"Why don\u0027t I see opportunities I know need no test?","a":"Because we only list an opportunity here when its source explicitly says the test is not required. Sources that say nothing about language are left out so the information is never wrong."},{"q":"Can I apply now and bring the certificate later?","a":"For some scholarships, yes \u2014 the certificate is a condition for final admission, not for applying. Read the eligibility section of each opportunity."}],"fr":[{"q":"La langue n\u0027a-t-elle donc pas d\u0027importance ?","a":"Si. Le certificat n\u0027est pas requis, mais la plupart de ces opportunit\u00E9s se d\u00E9roulent en anglais ou en fran\u00E7ais et peuvent demander une attestation de votre universit\u00E9 ou un entretien."},{"q":"Pourquoi certaines opportunit\u00E9s sans test n\u0027apparaissent-elles pas ?","a":"Nous ne listons ici que celles dont la source dit explicitement que le test n\u0027est pas requis. Les sources muettes sur la langue sont exclues."},{"q":"Puis-je postuler puis fournir le certificat plus tard ?","a":"Pour certaines bourses, oui : le certificat conditionne l\u0027admission finale, pas la candidature. Lisez les crit\u00E8res de chaque opportunit\u00E9."}]}', N'{"type":[],"field":[],"noIelts":true}', 1, 24, GETDATE(), GETDATE());
INSERT INTO LandingPages (Slug, TitleAr, TitleEn, TitleFr, IntroAr, IntroEn, IntroFr, FaqJson, FilterJson, IsPublished, SortOrder, CreatedAt, UpdatedAt) VALUES (N'climate-fellowships', N'زمالات مناخية للشباب من الوطن العربي', N'Climate fellowships for youth from the Arab world', N'Fellowships climat pour les jeunes du monde arabe', N'زمالات في العمل المناخي والسياسات المناخية والانتقال العادل والتكيّف: برامج ممولة لعدة أشهر أو سنة لدى المنظمات الدولية ومراكز الأبحاث والجامعات، للباحثين الشباب والناشطين والمهنيين من الوطن العربي. نعرض لكل زمالة من تقبل (الدول، المرحلة، الخبرة)، وما تقدّمه (راتب، سفر، إرشاد)، وموعدها ورابطها الرسمي، ونخبرك حين تفتح دورتها القادمة إن كانت مغلقة الآن. الزمالات المناخية هي أسرع طريق إلى مؤتمرات الأطراف وشبكات القيادة المناخية الدولية.', N'Fellowships in climate action, climate policy, just transition and adaptation: funded programmes of a few months to a year with international organisations, think tanks and universities, for young researchers, activists and professionals from the Arab world. For each fellowship we show who can apply (countries, level, experience), what it offers (stipend, travel, mentoring), its deadline and official link — and we alert you when the next cycle opens if it is closed now. Climate fellowships are the fastest route into COP delegations and international climate leadership networks.', N'Fellowships en action climatique, politiques climatiques, transition juste et adaptation : programmes financés de quelques mois à un an auprès d''organisations internationales, de centres de recherche et d''universités, pour jeunes chercheurs, militants et professionnels du monde arabe. Pour chaque fellowship : qui peut postuler, ce qu''il offre (allocation, voyage, mentorat), la date limite et le lien officiel, avec une alerte à l''ouverture du prochain cycle. Les fellowships climat ouvrent la voie aux délégations COP et aux réseaux internationaux.', @faq, N'{"type":["Fellowships"],"field":[],"theme":"Climate"}', 1, 25, GETDATE(), GETDATE());
INSERT INTO LandingPages (Slug, TitleAr, TitleEn, TitleFr, IntroAr, IntroEn, IntroFr, FaqJson, FilterJson, IsPublished, SortOrder, CreatedAt, UpdatedAt) VALUES (N'masters-scholarships', N'منح الماستر لشباب الوطن العربي', N'Master''s scholarships for youth in the Arab world', N'Bourses de master pour les jeunes du monde arabe', N'منح الماجستير المفتوحة الآن لحَمَلة البكالوريوس من الوطن العربي: ممولة بالكامل أو جزئيًا، في ألمانيا وتركيا وبريطانيا وكندا واليابان وفرنسا وهولندا والسويد وغيرها، في البيئة والطاقة والمياه والهندسة والعلوم والإدارة والسياسات. نعرض لكل منحة الدول المقبولة وشهادة اللغة المطلوبة والموعد النهائي ورابط التقديم الرسمي. أغلب منح الماستر تفتح مرة في السنة بين أكتوبر ومارس، فابدأ التجهيز قبل الموعد بشهور: كشف الدرجات، خطاب الدوافع، رسالتا توصية، وشهادة اللغة إن طُلبت.', N'Master''s scholarships open now to bachelor''s graduates from the Arab world: fully or partially funded, in Germany, Türkiye, the UK, Canada, Japan, France, the Netherlands, Sweden and beyond, in environment, energy, water, engineering, science, management and policy. For each scholarship we show accepted countries, the language test required, the deadline and the official link. Most master''s scholarships open once a year between October and March, so start preparing months ahead: transcript, motivation letter, two recommendation letters and a language certificate if required.', N'Bourses de master ouvertes maintenant aux titulaires d''une licence du monde arabe : entièrement ou partiellement financées, en Allemagne, Turquie, Royaume-Uni, Canada, Japon, France, Pays-Bas, Suède et ailleurs, en environnement, énergie, eau, ingénierie, sciences, gestion et politiques publiques. Pour chaque bourse : pays acceptés, test de langue requis, date limite et lien officiel. La plupart ouvrent une fois par an entre octobre et mars : préparez relevé de notes, lettre de motivation, deux recommandations et certificat de langue.', @faq, N'{"type":["Scholarships"],"degree":"Master","field":[]}', 1, 26, GETDATE(), GETDATE());
INSERT INTO LandingPages (Slug, TitleAr, TitleEn, TitleFr, IntroAr, IntroEn, IntroFr, FaqJson, FilterJson, IsPublished, SortOrder, CreatedAt, UpdatedAt) VALUES (N'phd-scholarships', N'منح الدكتوراه لشباب الوطن العربي', N'PhD scholarships for youth in the Arab world', N'Bourses de doctorat pour les jeunes du monde arabe', N'منح الدكتوراه المفتوحة الآن لحَمَلة الماجستير من الوطن العربي: ممولة بالكامل مع راتب شهري في الغالب، في الجامعات ومراكز الأبحاث في أوروبا وآسيا وأمريكا الشمالية، في المناخ والطاقة والمياه والبيئة والهندسة والعلوم. نعرض لكل منحة الدول المقبولة والمجالات والموعد ورابط التقديم الرسمي. الدكتوراه تحتاج في الغالب مقترح بحث ومراسلة مشرف محتمل قبل التقديم، فابدأ بذلك مبكرًا، وتابع البرامج المتكررة لنخبرك حين تفتح دورتها.', N'PhD scholarships open now to master''s graduates from the Arab world: usually fully funded with a monthly stipend, at universities and research centres in Europe, Asia and North America, in climate, energy, water, environment, engineering and science. For each scholarship we show accepted countries, fields, deadline and the official link. A PhD usually needs a research proposal and contact with a potential supervisor before applying, so start that early — and follow recurring programmes so we can tell you when their next cycle opens.', N'Bourses de doctorat ouvertes maintenant aux titulaires d''un master du monde arabe : généralement entièrement financées avec allocation mensuelle, dans des universités et centres de recherche d''Europe, d''Asie et d''Amérique du Nord, en climat, énergie, eau, environnement, ingénierie et sciences. Pour chaque bourse : pays acceptés, domaines, date limite et lien officiel. Un doctorat exige souvent un projet de recherche et un contact préalable avec un directeur : commencez tôt et suivez les programmes récurrents.', @faq, N'{"type":["Scholarships"],"degree":"PhD","field":[]}', 1, 27, GETDATE(), GETDATE());
INSERT INTO LandingPages (Slug, TitleAr, TitleEn, TitleFr, IntroAr, IntroEn, IntroFr, FaqJson, FilterJson, IsPublished, SortOrder, CreatedAt, UpdatedAt) VALUES (N'remote-internships', N'تدريب عن بُعد للطلاب والخريجين', N'Remote internships for students and graduates', N'Stages à distance pour étudiants et diplômés', N'فرص تدريب عن بُعد مفتوحة الآن للطلاب والخريجين من الوطن العربي: مع المنظمات الدولية والشركات الناشئة والجامعات، من بلدك وبساعات مرنة، بأجر أو بشهادة معتمدة. التدريب عن بُعد يفتح لك خبرة دولية بلا تأشيرة ولا تكاليف سفر، ويُحتسب في طلبات المنح والزمالات لاحقًا. نعرض لكل فرصة الجهة ومدتها وشروطها والموعد ورابط التقديم المباشر، ويمكن التقديم بلا حساب. رشّح بالمجال أو ببلد الجهة، واحفظ ما يعنيك لنذكّرك قبل موعده بأسبوع.', N'Remote internships open now to students and graduates from the Arab world: with international organisations, start-ups and universities, from your own country and on flexible hours, paid or with a recognised certificate. A remote internship gives you international experience without a visa or travel costs, and it counts in scholarship and fellowship applications later. For each one we show the organisation, duration, conditions, deadline and a direct application link — no account needed.', N'Stages à distance ouverts maintenant aux étudiants et diplômés du monde arabe : organisations internationales, start-ups et universités, depuis votre pays et à horaires flexibles, rémunérés ou avec attestation. Un stage à distance apporte une expérience internationale sans visa ni frais de voyage, valorisable ensuite pour les bourses et fellowships. Pour chaque offre : organisation, durée, conditions, date limite et lien direct, sans compte.', @faq, N'{"type":["Internships"],"field":[],"remote":true}', 1, 28, GETDATE(), GETDATE());
INSERT INTO LandingPages (Slug, TitleAr, TitleEn, TitleFr, IntroAr, IntroEn, IntroFr, FaqJson, FilterJson, IsPublished, SortOrder, CreatedAt, UpdatedAt) VALUES (N'women', N'فرص للنساء والفتيات في الوطن العربي', N'Opportunities for women and girls in the Arab world', N'Opportunités pour les femmes et les filles du monde arabe', N'منح وزمالات وبرامج قيادة وتدريب مخصصة للنساء والفتيات من الوطن العربي: في العلوم والتكنولوجيا والهندسة والمناخ وريادة الأعمال والقيادة، من منظمات دولية وجامعات ومؤسسات تدعم مشاركة المرأة. نعرض هنا فقط الفرص التي ينص مصدرها على أنها للنساء، مع الدول المقبولة والمرحلة والتمويل والموعد ورابط التقديم الرسمي. إن كنتِ تبحثين عن فرص عامة أيضًا، فكل الفرص الأخرى مفتوحة لكِ كذلك؛ هذه الصفحة تجمع المخصص فقط.', N'Scholarships, fellowships, leadership and training programmes reserved for women and girls from the Arab world: in science, technology, engineering, climate, entrepreneurship and leadership, from international organisations, universities and foundations that support women''s participation. Only opportunities whose source states they are for women appear here, with accepted countries, level, funding, deadline and the official link. All other opportunities on the site are open to you too; this page gathers the dedicated ones only.', N'Bourses, fellowships, programmes de leadership et de formation réservés aux femmes et aux filles du monde arabe : sciences, technologie, ingénierie, climat, entrepreneuriat et leadership, auprès d''organisations internationales, d''universités et de fondations. Seules les opportunités dont la source précise qu''elles sont destinées aux femmes apparaissent ici, avec pays acceptés, niveau, financement, date limite et lien officiel. Toutes les autres opportunités du site vous sont ouvertes aussi.', @faq, N'{"type":[],"field":[],"women":true}', 1, 29, GETDATE(), GETDATE());
