-- الدفعة الأولى من صفحات النية (36 صفحة) كما تولّدها Data/LandingPageSeed.cs، بصيغة SQL لتشغيلها في SQL Studio حين يتعذّر زر «استيراد الدفعة الأولى».
-- نُفّذ على قاعدة الإنتاج في 2026-11-04 (النتيجة: 36 صفحة منشورة). آمن للتكرار: الموجود بالـslug لا يُمسّ. القوالب المكرّرة (المقدمات حسب الدولة والأسئلة الشائعة) تُركّب بـREPLACE.
-- تحقق من تطابقه مع الكود: شُغّل على LocalDB داخل معاملة مُلغاة وقورنت الصفوف الـ36 حقلًا حقلًا مع LandingPageSeed.All — بلا فروق.

DECLARE @faq nvarchar(max) = N'{"ar":[{"q":"\u0643\u064A\u0641 \u0623\u0639\u0631\u0641 \u0625\u0646 \u0643\u0646\u062A \u0645\u0624\u0647\u064E\u0651\u0644\u064B\u0627 \u0644\u0641\u0631\u0635\u0629 \u0647\u0646\u0627\u061F","a":"\u0627\u0641\u062A\u062D \u0627\u0644\u0641\u0631\u0635\u0629 \u0648\u0627\u0642\u0631\u0623 \u0642\u0633\u0645 \u00AB\u0634\u0631\u0648\u0637 \u0627\u0644\u0623\u0647\u0644\u064A\u0629\u00BB: \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0645\u0642\u0628\u0648\u0644\u0629 \u0648\u0627\u0644\u0645\u0631\u062D\u0644\u0629 \u0648\u0627\u0644\u0639\u0645\u0631 \u0648\u0634\u0647\u0627\u062F\u0629 \u0627\u0644\u0644\u063A\u0629. \u0623\u0648 \u0623\u062C\u0628 \u0639\u0646 8 \u0623\u0633\u0626\u0644\u0629 \u0641\u064A \u00AB\u0628\u0648\u0635\u0644\u0629\u00BB \u0641\u0646\u0639\u0631\u0636 \u0644\u0643 \u0641\u0642\u0637 \u0645\u0627 \u062A\u0624\u0647\u064E\u0651\u0644 \u0644\u0647\u060C \u0645\u0639 \u0633\u0628\u0628 \u0644\u0643\u0644 \u0641\u0631\u0635\u0629."},{"q":"\u0647\u0644 \u0623\u062D\u062A\u0627\u062C \u062D\u0633\u0627\u0628\u064B\u0627 \u0644\u0644\u062A\u0642\u062F\u064A\u0645\u061F","a":"\u0644\u0644\u0648\u0638\u0627\u0626\u0641 \u0648\u0627\u0644\u062A\u062F\u0631\u064A\u0628 \u0648\u0627\u0644\u062A\u0637\u0648\u0639 \u0644\u0627\u061B \u0631\u0627\u0628\u0637 \u0627\u0644\u062A\u0642\u062F\u064A\u0645 \u0638\u0627\u0647\u0631 \u0645\u0628\u0627\u0634\u0631\u0629. \u0644\u0644\u0645\u0646\u062D \u0648\u0627\u0644\u0632\u0645\u0627\u0644\u0627\u062A \u0648\u0627\u0644\u0645\u0624\u062A\u0645\u0631\u0627\u062A \u0648\u0627\u0644\u0645\u0633\u0627\u0628\u0642\u0627\u062A \u0646\u0637\u0644\u0628 \u062D\u0633\u0627\u0628\u064B\u0627 \u0645\u062C\u0627\u0646\u064A\u064B\u0627 \u0648\u062A\u0623\u0643\u064A\u062F \u0628\u0631\u064A\u062F\u0643 \u0642\u0628\u0644 \u0632\u0631 \u00AB\u0642\u062F\u0651\u0645 \u0627\u0644\u0622\u0646\u00BB\u060C \u0644\u0646\u0630\u0643\u0651\u0631\u0643 \u0628\u0627\u0644\u0645\u0648\u0639\u062F \u0648\u0646\u062A\u0627\u0628\u0639 \u0645\u0639\u0643."},{"q":"\u0643\u0645 \u0645\u0631\u0629 \u062A\u064F\u062D\u062F\u064E\u0651\u062B \u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062D\u0629\u061F","a":"\u064A\u0648\u0645\u064A\u064B\u0627. \u062A\u064F\u0636\u0627\u0641 \u0627\u0644\u0641\u0631\u0635 \u0627\u0644\u062C\u062F\u064A\u062F\u0629 \u0641\u0648\u0631 \u0646\u0634\u0631\u0647\u0627\u060C \u0648\u062A\u0638\u0647\u0631 \u0627\u0644\u0645\u0646\u062A\u0647\u064A\u0629 \u0641\u064A \u0622\u062E\u0631 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0628\u0639\u0644\u0627\u0645\u0629 \u00AB\u0645\u0646\u062A\u0647\u064A\u0629\u00BB \u062B\u0645 \u062A\u064F\u0632\u0627\u0644. \u0627\u062D\u0641\u0638 \u0627\u0644\u0641\u0631\u0635\u0629 \u0644\u0646\u0630\u0643\u0651\u0631\u0643 \u0642\u0628\u0644 \u0645\u0648\u0639\u062F\u0647\u0627 \u0628\u0623\u0633\u0628\u0648\u0639."}],"en":[{"q":"How do I know whether I qualify for an opportunity here?","a":"Open it and read the eligibility section: accepted countries, level, age and language test. Or answer 8 questions in the Compass and we show only what you qualify for, with a reason for each one."},{"q":"Do I need an account to apply?","a":"Not for jobs, internships and volunteering \u2014 the apply link is right there. For scholarships, fellowships, conferences and competitions we ask for a free account and a confirmed email before \u201CApply now\u201D, so we can remind you of the deadline and track your application with you."},{"q":"How often is this page updated?","a":"Daily. New opportunities appear as soon as they are published; closed ones move to the end with an \u201Cexpired\u201D badge and are then removed. Save an opportunity to be reminded a week before its deadline."}],"fr":[{"q":"Comment savoir si je suis \u00E9ligible \u00E0 une opportunit\u00E9 ici ?","a":"Ouvrez-la et lisez la section \u00AB crit\u00E8res d\u0027\u00E9ligibilit\u00E9 \u00BB : pays accept\u00E9s, niveau, \u00E2ge et test de langue. Ou r\u00E9pondez \u00E0 8 questions dans la Boussole : nous n\u0027affichons que ce \u00E0 quoi vous \u00EAtes \u00E9ligible, avec une raison pour chaque opportunit\u00E9."},{"q":"Faut-il un compte pour postuler ?","a":"Pas pour les emplois, stages et b\u00E9n\u00E9volat : le lien est direct. Pour les bourses, fellowships, conf\u00E9rences et concours, un compte gratuit et un e-mail confirm\u00E9 sont demand\u00E9s avant \u00AB Postuler \u00BB, pour vous rappeler la date limite et suivre votre candidature."},{"q":"\u00C0 quelle fr\u00E9quence cette page est-elle mise \u00E0 jour ?","a":"Chaque jour. Les nouvelles opportunit\u00E9s apparaissent d\u00E8s leur publication ; les cl\u00F4tur\u00E9es passent en fin de liste avec la mention \u00AB expir\u00E9e \u00BB puis sont retir\u00E9es. Enregistrez une opportunit\u00E9 pour un rappel une semaine avant la date limite."}]}';
DECLARE @cAr nvarchar(max) = N'كل الفرص المفتوحة الآن التي تقبل المتقدمين من {A}: منح دراسية ممولة بالكامل، وظائف خضراء، زمالات، تدريب، تطوع، مؤتمرات ومسابقات. تُعرض هنا الفرص التي تذكر {A} صراحةً في شروطها، إضافةً إلى المفتوحة لكل دول الوطن العربي أو للعالم كله، فلا تضيع عليك فرصة لأنها لم تذكر بلدك بالاسم. كل فرصة مكتوبة بثلاث لغات مع شروط الأهلية والموعد النهائي ورابط التقديم الرسمي، ونحدّث القائمة يوميًا ونزيل المنتهي. رشّح بالنوع أو المرحلة أو المجال، أو جرّب «بوصلة» لترى في دقيقتين ما تؤهَّل له أنت تحديدًا.', @cEn nvarchar(max) = N'Every opportunity open right now that accepts applicants from {E}: fully funded scholarships, green jobs, fellowships, internships, volunteering, conferences and competitions. This page lists opportunities that name {E} explicitly in their criteria, plus those open to the whole Arab world or to everyone, so you never miss one just because it did not mention your country by name. Each one is written in three languages with eligibility criteria, deadline and the official application link; we update the list daily and remove what has closed. Filter by type, level or field, or try the Compass to see in two minutes what you personally qualify for.', @cFr nvarchar(max) = N'Toutes les opportunités ouvertes maintenant qui acceptent les candidats de {F} : bourses entièrement financées, emplois verts, fellowships, stages, bénévolat, conférences et concours. Cette page présente celles qui citent {F} explicitement dans leurs critères, ainsi que celles ouvertes à tout le monde arabe ou au monde entier. Chacune est rédigée en trois langues avec ses critères, sa date limite et le lien officiel ; la liste est mise à jour chaque jour. Filtrez par type, niveau ou domaine, ou essayez la Boussole.';
DECLARE @cTAr nvarchar(200) = N'فرص للشباب في {A}: منح ووظائف وزمالات', @cTEn nvarchar(200) = N'Opportunities for youth in {E}: scholarships, jobs and fellowships', @cTFr nvarchar(200) = N'Opportunités pour les jeunes – {F} : bourses, emplois et fellowships';
DECLARE @c TABLE (Slug nvarchar(80), Iso nvarchar(2), Ar nvarchar(120), En nvarchar(120), Fr nvarchar(120), Ord int);
SELECT c.Slug, REPLACE(@cTAr, N'{A}', c.Ar), REPLACE(@cTEn, N'{E}', c.En), REPLACE(@cTFr, N'{F}', c.Fr), REPLACE(@cAr, N'{A}', c.Ar), REPLACE(@cEn, N'{E}', c.En), REPLACE(@cFr, N'{F}', c.Fr), @faq, N'{"type":[],"country":"' + c.Iso + N'","field":[]}', 1, c.Ord, GETDATE(), GETDATE()
FROM @c c WHERE NOT EXISTS (SELECT 1 FROM LandingPages p WHERE p.Slug = c.Slug);
DECLARE @hAr nvarchar(max) = N'المنح الدراسية المفتوحة الآن للدراسة في {A}، للطلاب من الوطن العربي: بكالوريوس وماستر ودكتوراه، ممولة بالكامل أو جزئيًا، من الحكومة والجامعات والمؤسسات. نعرض لكل منحة الدول المقبولة والمرحلة وشهادة اللغة المطلوبة وما يغطيه التمويل والموعد النهائي ورابط التقديم الرسمي، ونخبرك حين تفتح دورة البرامج المتكررة. اقرأ شروط كل منحة بدقة؛ أغلب منح {A} تفتح مرة واحدة في السنة وتغلق قبل بداية العام الدراسي بشهور.', @hEn nvarchar(max) = N'Scholarships open right now to study in {E}, for students from the Arab world: bachelor''s, master''s and PhD, fully or partially funded, from the government, universities and foundations. For each scholarship we show accepted countries, level, the language test required, what the funding covers, the deadline and the official link — and we tell you when recurring programmes open their next cycle. Read each scholarship''s conditions carefully; most scholarships in {E} open once a year and close months before the academic year starts.', @hFr nvarchar(max) = N'Bourses ouvertes maintenant pour étudier en {F}, pour les étudiants du monde arabe : licence, master et doctorat, entièrement ou partiellement financées, par l''État, les universités et des fondations. Pour chaque bourse : pays acceptés, niveau, test de langue requis, couverture du financement, date limite et lien officiel, avec une alerte à l''ouverture des programmes récurrents. Lisez bien les conditions : la plupart ouvrent une fois par an et se clôturent des mois avant la rentrée.';
DECLARE @hTAr nvarchar(200) = N'منح دراسية في {A} لشباب الوطن العربي', @hTEn nvarchar(200) = N'Scholarships in {E} for youth in the Arab world', @hTFr nvarchar(200) = N'Bourses d''études – {F} – pour les jeunes du monde arabe';
DECLARE @h TABLE (Slug nvarchar(80), Iso nvarchar(2), Ar nvarchar(120), En nvarchar(120), Fr nvarchar(120), Ord int);
SELECT c.Slug, REPLACE(@hTAr, N'{A}', c.Ar), REPLACE(@hTEn, N'{E}', c.En), REPLACE(@hTFr, N'{F}', c.Fr), REPLACE(@hAr, N'{A}', c.Ar), REPLACE(@hEn, N'{E}', c.En), REPLACE(@hFr, N'{F}', c.Fr), @faq, N'{"type":["Scholarships"],"field":[],"host":"' + c.Iso + N'"}', 1, c.Ord, GETDATE(), GETDATE()
FROM @h c WHERE NOT EXISTS (SELECT 1 FROM LandingPages p WHERE p.Slug = c.Slug);
IF NOT EXISTS (SELECT 1 FROM LandingPages WHERE Slug = N'arab-world')
IF NOT EXISTS (SELECT 1 FROM LandingPages WHERE Slug = N'fully-funded')
IF NOT EXISTS (SELECT 1 FROM LandingPages WHERE Slug = N'no-ielts')
IF NOT EXISTS (SELECT 1 FROM LandingPages WHERE Slug = N'climate-fellowships')
IF NOT EXISTS (SELECT 1 FROM LandingPages WHERE Slug = N'masters-scholarships')
IF NOT EXISTS (SELECT 1 FROM LandingPages WHERE Slug = N'phd-scholarships')
IF NOT EXISTS (SELECT 1 FROM LandingPages WHERE Slug = N'remote-internships')
IF NOT EXISTS (SELECT 1 FROM LandingPages WHERE Slug = N'women')
SELECT COUNT(*) AS landing_pages, SUM(CASE WHEN IsPublished = 1 THEN 1 ELSE 0 END) AS published FROM LandingPages;
